resource "aws_bedrockagentcore_agent_runtime" "example_resource" {
  agent_runtime_name = "example_resource"
  role_arn           = aws_iam_role.example_resource.arn

  agent_runtime_artifact {
    container_configuration {
      container_uri = "123456789012.dkr.ecr.us-east-1.amazonaws.com/example:latest"
    }
  }

  network_configuration {
    network_mode = "VPC"
  }

  # Critical: without this block the runtime accepts any caller holding IAM permissions
  authorizer_configuration {
    custom_jwt_authorizer {
      discovery_url   = "https://example.com/.well-known/openid-configuration"
      allowed_clients = ["example-client-id"]
    }
  }
}
```
